import{z as i,x as n,o as e,c as s,q as B,j as l,D as E,d as t,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"内核工程收束","description":"","frontmatter":{"title":"内核工程收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ak-map.md","filePath":"llm/ak-map.md","lastUpdated":1791063341000}'),m={name:"llm/ak-map.md"};function d(p,a,h,D,_,f){const A=n("Mermaid");return e(),s("div",null,[a[2]||(a[2]=B('<h1 id="内核工程收束" tabindex="-1">内核工程收束 <a class="header-anchor" href="#内核工程收束" aria-label="Permalink to &quot;内核工程收束&quot;">​</a></h1><div class="epigraph"><p>一套精确的数学、一份片上预算、一群在块上做文章的变体、一把测量的尺——注意力内核工程的全部家当。</p><footer>—— 据 Dao et al., 2022；Dao, 2023；Kwon et al., 2023 整理</footer></div><p><a href="/llm/ak-multi-backend">上一课</a>把内核送上不同硬件，交付链接完。本课是全课程的地图与收束：把三个单元十三课收成一张能带走的清单，并交代本课程没有覆盖的邻接地带。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十三课散在机制、变体、工程三个单元里，离开时要回答三个问题。不变量是什么——变体满天飞，哪些东西一动就不是注意力内核了。变体动了什么——新论文层出不穷，它们在共享坐标系的哪条轴上。拿到新任务先做什么——新形状、新硬件、新变体进门时的操作顺序。收束课的任务不是重复，是把十三课压成可执行的判断。</p><p><span class="marginnote">为什么重要：拿到一篇「新注意力」论文时，最贵的错误是从零重读它的内核推导。先对坐标系：它动的是头、地址、图、状态、数值哪一条，然后直接翻那一课的机制账——大多数「新」结构只是旧坐标上的新值，十分钟就能预判它的性能形状。</span></p><h3 id="五条坐标一张图" tabindex="-1">五条坐标一张图 <a class="header-anchor" href="#五条坐标一张图" aria-label="Permalink to &quot;五条坐标一张图&quot;">​</a></h3><p>变体单元的五课各动一条坐标：头维（GQA/MQA 改读哪几套 KV）、地址维（分页改 KV 住在哪）、图维（稀疏改哪些块不算）、状态维（线性改 softmax 本身成什么）、数值维（低精度改每步数是什么格式）。坐标互相正交：一个现代长上下文模型常常同时动三四条。工程化单元的五课不动坐标，动的是形状（投机）、并行度（长序列）、尺（基准）与分发（调优、移植）。</p>',8)),(e(),l(r,null,{default:E(()=>[o(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20LR%0A%20%20V%5B%22%E6%B3%A8%E6%84%8F%E5%8A%9B%E5%8F%98%E4%BD%93%E5%8A%A8%E4%BB%80%E4%B9%88%22%5D%20--%3E%20A%5B%22%E5%A4%B4%E7%BB%B4%3A%20%E8%AF%BB%E5%87%A0%E5%A5%97%20KV%20(GQA%2FMQA)%22%5D%0A%20%20V%20--%3E%20B%5B%22%E5%9C%B0%E5%9D%80%E7%BB%B4%3A%20KV%20%E4%BD%8F%E5%9C%A8%E5%93%AA%20(%E5%88%86%E9%A1%B5)%22%5D%0A%20%20V%20--%3E%20C%5B%22%E5%9B%BE%E7%BB%B4%3A%20%E5%93%AA%E4%BA%9B%E5%9D%97%E4%B8%8D%E7%AE%97%20(%E7%A8%80%E7%96%8F)%22%5D%0A%20%20V%20--%3E%20D%5B%22%E7%8A%B6%E6%80%81%E7%BB%B4%3A%20softmax%20%E6%8D%A2%E6%88%90%E4%BB%80%E4%B9%88%20(%E7%BA%BF%E6%80%A7)%22%5D%0A%20%20V%20--%3E%20E%5B%22%E6%95%B0%E5%80%BC%E7%BB%B4%3A%20%E6%AF%8F%E4%B8%AA%E6%95%B0%E4%BB%80%E4%B9%88%E6%A0%BC%E5%BC%8F%20(%E4%BD%8E%E7%B2%BE%E5%BA%A6)%22%5D%0A%20%20A%20--%3E%20O%5B%22%E5%9D%90%E6%A0%87%E6%AD%A3%E4%BA%A4%2C%20%E5%B8%B8%E5%90%8C%E6%97%B6%E5%8A%A8%E4%B8%89%E5%9B%9B%E6%9D%A1%22%5D%0A%20%20B%20--%3E%20O%0A%20%20C%20--%3E%20O%0A%20%20D%20--%3E%20O%0A%20%20E%20--%3E%20O%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>带走一份操作顺序。新形状进门：先记<a href="/llm/ak-memory-access">内存访问模式</a>的账，判断带宽还是算力绑定；再查 <a href="/llm/ak-smem-register-budget">shared memory 与寄存器预算</a>定 tile 候选；接口先钉——头映射、页表、掩码图、变长，参照 <a href="/llm/ak-paged-kv-kernel">分页 KV 的内核接口</a>与投机的变长 \\(q\\)；然后进 <a href="/llm/ak-benchmark-methodology">内核基准测试方法论</a>的网格，验收与计时同权；赢家进 <a href="/llm/ak-autotuning">autotuning 实践</a>的配置表，缓存键把形状桶与 \\(n_q\\) 记全；换硬件时按<a href="/llm/ak-multi-backend">多后端移植</a>分层走。新变体进门：先判断它动的是五条坐标里的哪一条，再沿那一课的机制读它的内核账——新稀疏是图维的新图，新量化是数值维的新格式，新 KV 布局是地址维的新译址。</p>',2)),(e(),l(r,null,{default:E(()=>[o(A,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E5%9F%BA%E7%A1%80%E6%9C%BA%E5%88%B6%EF%BC%9Atiling%20%E4%B8%8E%20online%20softmax%22%5D%20--%3E%20G%5B%22%E8%AE%BF%E5%AD%98%E8%B4%A6%EF%BC%9A%E5%AD%97%E8%8A%82%E4%BC%98%E5%85%88%E4%BA%8E%20FLOPs%22%5D%0A%20%20G%20--%3E%20H%5B%22%E7%89%87%E4%B8%8A%E9%A2%84%E7%AE%97%EF%BC%9Asmem%20%E4%B8%8E%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20H%20--%3E%20V%5B%22%E4%BA%94%E6%9D%A1%E5%8F%98%E4%BD%93%E5%9D%90%E6%A0%87%EF%BC%9A%E5%A4%B4%E3%80%81%E5%9C%B0%E5%9D%80%E3%80%81%E5%9B%BE%E3%80%81%E7%8A%B6%E6%80%81%E3%80%81%E6%95%B0%E5%80%BC%22%5D%0A%20%20V%20--%3E%20E%5B%22%E5%B7%A5%E7%A8%8B%E5%8C%96%EF%BC%9A%E5%BD%A2%E7%8A%B6%E3%80%81%E5%B9%B6%E8%A1%8C%E5%BA%A6%E3%80%81%E5%9F%BA%E5%87%86%E3%80%81%E8%B0%83%E4%BC%98%E3%80%81%E7%A7%BB%E6%A4%8D%22%5D%0A%20%20E%20--%3E%20M%5B%22%E4%BA%A4%E4%BB%98%E9%93%BE%EF%BC%9A%E6%8E%A5%E5%8F%A3%E2%86%92%E7%BD%91%E6%A0%BC%E2%86%92%E9%85%8D%E7%BD%AE%E8%A1%A8%E2%86%92%E8%B7%AF%E7%94%B1%22%5D%0A%20%20M%20-.-%3E%20F%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么这套清单能复用：因为变体多而坐标少。五条坐标加上「精确 softmax 的结合律合并」这条不变量，构成了一个足够小的封闭集——新工作要么在坐标上取新值，要么把坐标组合，要么（罕见地）换不变量，比如线性注意力把归一化从行内 softmax 换成状态递推，那是状态维的极值点。内核库的 API 形状恰好印证：FlashInfer 的对象是分页、变长、共享前缀，FlexAttention 的对象是掩码图与分数修改——库的接口分裂就是坐标的接口化。而第一课的 \\((m,l,O)\\) 三元组从块间走到段间、从单卡走到多卡，全程未改——这是「不变量」一词的工程含义：它不是没被碰到，是被碰到时按同一条结合律合并。</p><p><span class="marginnote">一条自检链：访存账 → 预算表 → 接口合同 → 数值容差 → 冲刷 L2 的基准 → 缓存键是否记全。六步省掉任何一步，问题都会在生产形状上回来——而且回来的形态是延迟或正确性，不是报错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程没有覆盖的地带要交代清楚。反向与训练内核只借了一角（重算与 attention backward），训练期的调度与显存换入换出是训练系统的题。KV 的压缩、量化与驱逐是 KV 管理课程的题目——本课只负责把它们读得快，不决定它们存什么。请求调度、批处理与多租户在服务课程。硬件微架构的细节（流水、互连、缓存层次）归体系结构。这些课程接的正是本课程交出的接口：页表、变长、坐标化的变体、可复现的数字。</p><p><span class="marginnote">常见误区：以为「内核写完就交付了」。实际上页表、变长、头映射这些接口一旦被引擎和框架依赖，就比内核本身活得久——换硬件只需重写核，接口一动却要整个生态跟着改。所以接口要比实现更谨慎，这也是交付链「接口先行」的原因。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>不变量是精确 softmax 的结合律合并：\\((m,l,O)\\) 从块间、段间到设备间一路未改。</li><li>变体收进五条坐标：头、地址、图、状态、数值；新工作多半是坐标上的新值或新组合。</li><li>快来自字节不过 HBM；每一步优化先过访存账与片上预算，再谈指令。</li><li>交付链固定：接口先行、基准网格与验收同权、配置表带键、路由按后端能力。</li><li>接口比内核活得久：页表、变长与头映射进接口后，硬件换了合同仍在。</li><li>出处：Dao et al., 2022；Dao, <em>FlashAttention-2</em>, 2023；Kwon et al., SOSP 2023；其余各课口径随课标注。</li></ul>',8))])}const C=i(m,[["render",d]]);export{u as __pageData,C as default};
